// Auto-generated payment method logo buffers (base64). Robust in client and SSR runtimes.
// Sources: src/assets/webpay.png, src/assets/santander.png, src/assets/checklist.png
const WEBPAY_BASE64 = '';
const SANTANDER_BASE64 = '';
const CHECKLIST_BASE64 = '';

function toBytes(base64: string): Uint8Array {
  const bin = atob(base64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

export function getWebpayLogoBuffer(): Uint8Array {
  return toBytes(WEBPAY_BASE64);
}

export function getSantanderLogoBuffer(): Uint8Array {
  return toBytes(SANTANDER_BASE64);
}

export function getChecklistIconBuffer(): Uint8Array {
  return toBytes(CHECKLIST_BASE64);
}
